SELECT *, FIRST_VALUE(method, TRUE) OVER (PARTITION BY order_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_method, ROW_NUMBER() OVER (PARTITION BY status, order_id ORDER BY amount DESC, id) AS seq_no, SUM(amount) OVER (PARTITION BY status, order_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount, FIRST_VALUE(method) IGNORE NULLS OVER (PARTITION BY MONTH(paid_at), method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_method_2 FROM payments;
